{
  "name": "@adrianlzt/opencode-show-tools",
  "main": "dist/index.js",
  "version": "1.0.0",
  "description": "OpenCode plugin that adds a /tools command to list all available tools",
  "author": "shekohex",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tools",
    "slash-command"
  ],
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build:prod": "vite build --mode production",
    "prepack": "npm run build:prod",
    "lint": "biome lint .",
    "lint:fix": "biome lint --write .",
    "format": "biome format .",
    "format:fix": "biome format --write ."
  },
  "devDependencies": {
    "@biomejs/biome": "2.3.13",
    "@types/bun": "^1.3.8",
    "typescript": "^5.9.3",
    "vite": "^7.3.1"
  },
  "peerDependencies": {
    "typescript": "^5"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.51",
    "@opencode-ai/sdk": "^1.1.51"
  }
}
